from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
M = partial(mk, "somatic", "somatic", "activity")
DSM_M = DSM("Somatic Symptom and Related Disorders")
NHS_FND = src("src-nhs-fnd", "Functional neurological disorder (FND)", "NHS", "https://www.nhs.uk/conditions/functional-neurological-disorder/", note="Not opened.")
FNDHOPE = src("src-fndhope", "FND Hope: peer support", "FND Hope International", "https://fndhope.org/", seen=True)
NEUROSYM = src("src-neurosymptoms", "neurosymptoms.org: a guide to functional neurological disorder", "Prof Jon Stone (University of Edinburgh)", "https://neurosymptoms.org/", note="Not opened; widely used patient resource.")
M_COMMS = ["mind-side-by-side", "adaa-online-support-group", "sane-forums-australia"]

CARDS.append(M("somatic-symptom-disorder", "Somatic Symptom Disorder", "Real symptoms, and a worry about them that takes over", ["somatization (older term)", "SSD"], "F45.1",
 "One or more distressing physical symptoms, plus excessive thoughts, worry, or time spent on them, lasting six months or more.",
 "Somatic symptom disorder is not about imaginary symptoms. The pain, tiredness, dizziness, or stomach problems are real, whether or not tests explain them. What defines the disorder is the response: constant worry about the symptoms, thinking they're far more serious than doctors say, and life revolving around them, for six months or more. Mind and body are one system, and stress, trauma, and mood change how the body feels. Treatment addresses both, and it helps.",
 ["Eleven specialists, no diagnosis, and a GP who finally asked how I was coping instead of ordering another scan.", "The pain was real. So was the fact that I'd stopped living while I waited for an answer.", "CBT didn't make the symptoms vanish. It gave me my life back around them."],
 ["One or more physical symptoms that cause distress or disrupt daily life", "Constant worry about the symptoms, or believing they're very serious", "Lots of time and energy spent on symptoms or health concerns", "Lasting six months or more, even if the specific symptom changes", "Often many appointments and tests without relief", "Frequently alongside anxiety, depression, or a past trauma"],
 [{"myth": "It means the symptoms are all in your head.", "fact": "The symptoms are real and felt in the body. The diagnosis is about the distress and preoccupation around them, which treatment can reduce."},
  {"myth": "If a test is normal, there's nothing wrong.", "fact": "Many real conditions have normal tests. Normal tests mean certain things are ruled out, not that nothing is happening."},
  {"myth": "Seeing a therapist means the doctor has given up.", "fact": "Mind-body treatment is the recommended care, often alongside medical management, because it's what works for this pattern."}],
 {"plain": "Somatic symptom disorder is common, affecting an estimated 4 to 6 in 100 adults, and a large share of people seen repeatedly in primary care.", "figure": "Estimated 4%–6% of adults (DSM-5-TR text and secondary summaries); around 5–7% in some reviews", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "The best approach is a steady relationship with one doctor who takes symptoms seriously, limits repeated tests, and schedules regular check-ins, combined with CBT or similar therapy focused on coping, reducing health worry, and getting back to activity. Treating depression and anxiety, often with an antidepressant prescribed and monitored by a doctor, improves symptoms too. Physiotherapy and graded activity help with pain and fatigue. Mindfulness-based approaches have some evidence.",
  "evidence_based_options": ["CBT for somatic symptoms and health anxiety", "A consistent primary care doctor with scheduled reviews rather than crisis visits", "Antidepressants for co-occurring depression, anxiety, or pain, prescribed and monitored by a doctor", "Graded activity, physiotherapy, and mindfulness-based approaches"],
  "self_help_that_supports_care": ["Keeping a symptom and stress diary to see links", "Returning to valued activities gradually rather than waiting to feel well", "Limiting online symptom searching", "Peer support with others living with persistent symptoms"],
  "guideline_refs": ["src-dsm"]},
 "If physical symptoms and the worry about them have taken over your life for months, ask your doctor about a mind-body approach alongside medical care. Keep seeing one trusted doctor rather than many.",
 "Having a medical illness, even a serious one, isn't somatic symptom disorder unless the worry and preoccupation are excessive. Illness anxiety disorder is fear of illness with few or no symptoms. Functional neurological disorder involves specific nervous-system symptoms.",
 "People with somatic symptom disorder often get their lives back long before their symptoms fully fade, and many symptoms ease once the fear around them does.",
 ["illness-anxiety-disorder", "functional-neurological-symptom-disorder", "generalized-anxiety-disorder", "major-depressive-disorder", "posttraumatic-stress-disorder", "psychological-factors-affecting-other-medical-conditions"],
 ["somatic-symptoms", "all-in-your-head", "catastrophizing", "cbt", "mindfulness"],
 M_COMMS, ("Soft line illustration of a person walking a gentle path with a walking pole, a doctor's appointment card in their pocket, and a friend alongside, trees and light. Pastel terracotta and sage.", "A person walks a gentle path with a walking pole alongside a friend under trees."),
 [DSM_M, src("src-nice-ng193", "Chronic pain (primary and secondary) in over 16s: assessment and management (NG193)", "NICE", "https://www.nice.org.uk/guidance/ng193", 2021, note="Not opened; relevant for persistent pain.")],
 qs=["Find a primary prevalence source."],
 cult="In many cultures, distress is expressed through the body first, and physical symptoms are the normal language of suffering. This is not a disorder in itself. Clinicians are advised to understand the person's own explanation for symptoms."))

CARDS.append(M("illness-anxiety-disorder", "Illness Anxiety Disorder", "Constant fear of having a serious illness", ["health anxiety", "hypochondriasis (outdated)"], "F45.21",
 "Being preoccupied with having or getting a serious illness despite few symptoms, either checking constantly or avoiding care.",
 "Illness anxiety disorder is intense, lasting fear of having or developing a serious illness, when there are few or no physical symptoms, or only mild ones. The person checks their body, researches symptoms, seeks repeated reassurance and tests, or, in the other pattern, avoids doctors entirely out of fear. Reassurance helps for a moment and then the fear returns. It's exhausting, it's very common, and it responds well to CBT.",
 ["Every headache was a tumour. Every ache was the start of something. I had more scans than my grandmother.", "The relief after a normal test lasted about a day. Then I'd find a new symptom.", "Therapy taught me that checking was the problem, not the solution."],
 ["Preoccupation with having or getting a serious illness", "Few or mild physical symptoms, or none", "High anxiety about health; easily alarmed by bodily sensations", "Repeatedly checking the body, researching, or seeking reassurance", "Or: avoiding doctors and hospitals out of fear", "Lasting six months or more, even if the feared illness changes"],
 [{"myth": "Hypochondriacs just want attention.", "fact": "The fear is genuine and distressing. Many people with health anxiety are ashamed of it and hide it."},
  {"myth": "One more test will settle it.", "fact": "Reassurance and testing feed the cycle. Learning to tolerate uncertainty is what ends it."},
  {"myth": "It's harmless worrying.", "fact": "Untreated health anxiety damages quality of life, relationships, and finances, and can delay care for real problems."}],
 {"plain": "Health anxiety affects somewhere between 1 and 5 in 100 adults, with higher rates in people attending medical clinics.", "figure": "Estimates range from 1.3% to 10% in the general population; around 3%–8% in medical outpatient settings (DSM-5-TR text and reviews)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "CBT for health anxiety is the first-line treatment, with strong evidence: it works on the beliefs about symptoms, reduces checking and reassurance-seeking, and builds tolerance of uncertainty. Internet-delivered CBT is effective too. Antidepressants (SSRIs), prescribed and monitored by a doctor, help many people, especially where there's depression. A steady relationship with one doctor who agrees a plan for tests and reviews helps.",
  "evidence_based_options": ["CBT for health anxiety, in person or online", "SSRI antidepressants, prescribed and monitored by a doctor", "An agreed plan with one doctor for check-ups and tests", "Mindfulness-based approaches as an addition"],
  "self_help_that_supports_care": ["Stopping symptom searching and body checking, gradually", "Asking loved ones to stop giving reassurance, by agreement", "Noticing anxiety's own body symptoms: racing heart, tingling, dizziness", "Scheduled 'worry time' instead of all-day worry"],
  "guideline_refs": ["src-nice-cg113"]},
 "If fear of illness is taking up hours of your day, driving repeated tests, or keeping you away from doctors, ask for CBT for health anxiety. Keep one doctor for real medical questions, and let them know about the anxiety too.",
 "Sensible attention to health, worry while awaiting results, or anxiety with a real diagnosis are not the disorder. Somatic symptom disorder involves significant symptoms; illness anxiety involves few or none. Fear of contamination with rituals is more likely OCD.",
 "Health anxiety has one of the best responses to CBT of any condition. People who checked their bodies hourly learn to live without the dread.",
 ["somatic-symptom-disorder", "generalized-anxiety-disorder", "obsessive-compulsive-disorder", "panic-disorder", "major-depressive-disorder"],
 ["catastrophizing", "intrusive-thoughts", "cbt", "ssri", "rumination"],
 M_COMMS, ("Soft line illustration of a person closing a laptop and going out to meet friends at a market, a phone with a 'worry time 6pm' reminder on the table. Pastel terracotta and sky blue.", "A person closes a laptop and heads out to meet friends at a market, a reminder note on the table."),
 [DSM_M, src("src-nice-cg113", "Generalised anxiety disorder and panic disorder in adults (CG113)", "NICE", "https://www.nice.org.uk/guidance/cg113", 2011, seen=True, note="Health anxiety is often treated under anxiety pathways; CBT-HA evidence from trials such as CHAMP (Tyrer et al.).")],
 qs=["Add CHAMP trial citation and a primary prevalence source.", "Verify a health-anxiety peer community (r/HealthAnxiety, No More Panic)."]))

CARDS.append(M("functional-neurological-symptom-disorder", "Functional Neurological Symptom Disorder (Conversion Disorder)", "Real neurological symptoms from a 'software' problem", ["FND", "functional neurological disorder", "conversion disorder", "dissociative seizures", "non-epileptic attacks"], "F44.4–F44.7 (by symptom type)",
 "Genuine weakness, seizures, tremor, or numbness caused by a problem in how the nervous system functions, not damage.",
 "Functional neurological disorder causes real, often disabling symptoms: limb weakness or paralysis, shaking, blackouts or seizure-like attacks, numbness, trouble walking, speaking, or swallowing. Scans and tests are normal because the structure of the nervous system is fine; the problem is in how the brain sends and receives signals, like a software fault in a working computer. It's one of the commonest reasons to see a neurologist. It's not faking and not 'all in the mind', and specific treatments help.",
 ["My legs stopped working at 28. Every scan was clear. One neurologist said it was stress and walked out. The next one explained FND and I finally had a plan.", "The seizures looked like epilepsy. They weren't. Understanding that was the start of them stopping.", "Specialist physio retrained my brain to trust my leg. I'm walking without the stick now."],
 ["Weakness, paralysis, tremor, or abnormal movements", "Blackouts or seizure-like attacks that aren't epilepsy", "Numbness, loss of sensation, vision or hearing changes", "Difficulty walking, speaking, or swallowing", "Symptoms that can vary with attention or distraction", "Normal scans; diagnosis by positive signs on examination"],
 [{"myth": "FND means you're faking or imagining it.", "fact": "FND is a genuine disorder of nervous-system function with recognizable signs on examination. Nobody chooses it."},
  {"myth": "FND is always caused by trauma.", "fact": "Trauma raises the risk, but many people with FND have no trauma history. Physical injury, illness, and stress can all trigger it."},
  {"myth": "Nothing can be done because the scans are normal.", "fact": "Normal scans are expected in FND. Specialist physiotherapy, psychological therapy, and education lead to real improvement."}],
 {"plain": "FND is common in neurology clinics, where it accounts for around 1 in 6 new patients. In the general population, new cases arise at roughly 4 to 12 per 100,000 people a year.", "figure": "Incidence of persistent functional neurological symptoms about 4–12 per 100,000 per year; around 16% of neurology outpatient referrals", "source_ref": "src-nhs-fnd", "note": "Figures from secondary summaries; needs a primary citation (e.g. Stone et al.)."},
 {"plain_summary": "Treatment starts with a clear, confident diagnosis and explanation; understanding the condition is itself therapeutic. Specialist physiotherapy retrains movement for weakness, tremor, and gait problems. Psychological therapy, especially CBT adapted for dissociative seizures, helps attacks. Occupational therapy and speech therapy address daily function. Treating co-occurring anxiety, depression, or pain helps. Multidisciplinary FND clinics exist in some areas. Medication isn't a treatment for FND itself.",
  "evidence_based_options": ["Clear diagnosis and education about FND", "Specialist FND physiotherapy for motor symptoms", "CBT adapted for dissociative (functional) seizures", "Multidisciplinary rehabilitation; treatment of co-occurring conditions"],
  "self_help_that_supports_care": ["Reading trusted FND resources, such as neurosymptoms.org", "Distraction techniques when symptoms flare, which can interrupt them", "Pacing activity rather than boom-and-bust", "Peer support with others who have FND"],
  "guideline_refs": ["src-neurosymptoms"]},
 "If you have neurological symptoms like weakness, seizures, or numbness, see a doctor for assessment. If you're told it's FND, ask for an explanation you understand and a referral to FND-informed physiotherapy or therapy. Any new seizure or sudden weakness needs emergency assessment.",
 "Epilepsy, stroke, multiple sclerosis, and other neurological diseases cause similar symptoms and are ruled out by neurologists; the two can co-exist. Factitious disorder and malingering involve deliberate deception, which FND does not.",
 "FND is treatable, and many people improve substantially or recover fully once they get the right diagnosis and the right rehabilitation.",
 ["somatic-symptom-disorder", "dissociative-amnesia", "posttraumatic-stress-disorder", "panic-disorder", "major-depressive-disorder", "factitious-disorder"],
 ["functional-symptoms", "dissociation", "all-in-your-head", "occupational-therapist"],
 ["fnd-hope-peer-support", "mind-side-by-side"],
 ("Soft line illustration of a person and a physiotherapist practising walking between parallel bars in a bright clinic, the person smiling, a whiteboard with 'brain retraining' sketched. Pastel terracotta and teal.", "A person practises walking between parallel bars with a physiotherapist in a bright clinic."),
 [DSM_M, NHS_FND, NEUROSYM, FNDHOPE],
 qs=["Add a primary epidemiology source (Stone et al.).", "Verify FND Action UK and r/FND before listing."],
 young="FND occurs in children and teenagers, often as functional seizures or weakness, and is frequently triggered by illness, injury, or stress. Outcomes are generally better in young people with early diagnosis.",
 subs=[{"title": "Symptom types", "icd10cm_code": "F44.4 / F44.5 / F44.6 / F44.7", "text": "With weakness or paralysis, abnormal movement, swallowing or speech symptoms (F44.4); with attacks or seizures (F44.5); with anaesthesia, sensory loss, or special sensory symptoms (F44.6); with mixed symptoms (F44.7)."}]))

CARDS.append(M("psychological-factors-affecting-other-medical-conditions", "Psychological Factors Affecting Other Medical Conditions", "When stress or behaviour makes a physical illness worse", [], "F54",
 "A diagnosis used when psychological or behavioural factors clearly worsen a medical condition or interfere with its treatment.",
 "This diagnosis isn't about a mental illness. It's for when stress, emotions, beliefs, or behaviours are clearly making a medical condition worse or getting in the way of treating it: anxiety that triggers asthma attacks, denial that delays cancer treatment, stress that drives up blood pressure, or distress that stops someone managing diabetes. Naming it helps the medical team address the psychological side as part of care, rather than treating body and mind separately.",
 ["My asthma is fine until I'm stressed. Then it's A&E. The respiratory nurse was the one who suggested I see a psychologist.", "I ignored the lump for a year because I couldn't face it. The diagnosis of 'psychological factors' on my notes stung, but it got me help.", "Managing diabetes with depression was impossible. Treating the depression made the diabetes manageable."],
 ["A medical condition that's clearly worsened by stress, mood, beliefs, or behaviours", "Psychological factors delaying recovery or interfering with treatment", "Patterns like denial, poor adherence, or stress-triggered flares", "The factor goes beyond what's expected and poses a health risk", "Not better explained by another mental disorder"],
 [{"myth": "This diagnosis means the illness is psychological.", "fact": "The illness is physical. The diagnosis flags that psychological factors are affecting it, so both can be treated."},
  {"myth": "It's a way of blaming the patient.", "fact": "It's a way of getting psychological support included in medical care. The aim is help, not blame."},
  {"myth": "Stress can't really affect physical disease.", "fact": "Stress and mood affect the immune system, blood pressure, pain, and health behaviours. The evidence is strong."}],
 {"plain": "This diagnosis is used across many medical settings; its frequency depends on the illness. Depression and anxiety are common in people with long-term physical conditions.", "figure": "No single prevalence figure; around 30% of people with long-term physical conditions have a co-occurring mental health condition (NHS estimates)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "Treatment is integrated: the medical team and a psychologist or therapist work together. CBT, stress management, and motivational approaches help with adherence and stress-triggered flares. Treating depression or anxiety, with any medication prescribed and monitored by a doctor, often improves the physical condition. Health psychologists specialize in exactly this. Peer support from others with the same illness helps people cope.",
  "evidence_based_options": ["CBT and stress-management approaches adapted to the medical condition", "Treatment of depression or anxiety, integrated with medical care", "Health psychology or liaison psychiatry input", "Condition-specific self-management programmes"],
  "self_help_that_supports_care": ["Noticing what stresses tend to come before flares", "Telling your medical team about mood and stress, not just symptoms", "Peer groups for your medical condition", "Small, steady habits for medication and appointments"],
  "guideline_refs": ["src-dsm"]},
 "If stress, mood, or avoidance are making a physical illness worse or harder to manage, tell your medical team and ask about psychological support alongside treatment. It's a normal part of good care.",
 "Having a mental illness alongside a medical condition is coded as both, not as this. Somatic symptom disorder is about distress over symptoms; this is about factors affecting an established illness.",
 "Treating the psychological side of a physical illness often brings the biggest improvement people have seen in years.",
 ["somatic-symptom-disorder", "major-depressive-disorder", "generalized-anxiety-disorder", "health-care-access-and-treatment-adherence"],
 ["stress", "coping-skills", "cbt"],
 M_COMMS, ("Soft line illustration of a person with an inhaler in their pocket doing calm breathing with a nurse in a bright clinic room, a plant on the window. Pastel terracotta and mint.", "A person practises calm breathing with a nurse in a bright clinic room."),
 [DSM_M, src("src-nhs-ltc", "Long-term conditions and mental health", "NHS / The King's Fund", "https://www.kingsfund.org.uk/insight-and-analysis/reports/long-term-conditions-and-mental-health", 2012, note="Not opened; source of the ~30% estimate.")],
 qs=["Find a primary prevalence source."], card_type="clinical-focus"))

CARDS.append(M("factitious-disorder", "Factitious Disorder", "Faking or causing illness without an obvious reason", ["Munchausen syndrome (older term)", "factitious disorder imposed on another (Munchausen by proxy)"], "F68.10 / F68.A",
 "Deliberately producing or faking illness in oneself, or in someone in one's care, without an obvious external reward.",
 "Factitious disorder is when a person deliberately fakes or causes illness or injury, in themselves (imposed on self) or in someone they care for, usually a child (imposed on another), without an outside motive like money. The driver is a deep need to be seen as ill or as a caregiver. It's rare and often rooted in trauma. Imposed on another is abuse and handled as child protection. Treatment is possible but hard, because the person often can't admit it.",
 ["I don't fully know why I did it. The hospital was the only place I felt looked after.", "Being confronted was devastating. Being offered therapy instead of just being discharged was what changed things.", "As the child it was done to, I grew up believing I was sick. Learning the truth took years."],
 ["Faking, exaggerating, or deliberately causing symptoms or injury", "Presenting oneself (or another) as ill, impaired, or injured", "No obvious external reward, like money or avoiding duties", "Often many hospital admissions, unusual or inconsistent test results, or symptoms that worsen when unobserved", "In 'imposed on another': a child with unexplained, recurring illness in one person's care"],
 [{"myth": "People with factitious disorder are just attention-seekers who should be ignored.", "fact": "It's a serious mental health condition, usually rooted in trauma. Ignoring it leaves the person, and sometimes a child, at real risk."},
  {"myth": "It's the same as malingering.", "fact": "Malingering is faking for an external gain, like money or avoiding work, and isn't a mental disorder. Factitious disorder has no such gain."},
  {"myth": "Somatic symptom disorder and FND are types of faking too.", "fact": "No. In those conditions symptoms are genuinely experienced. Factitious disorder is the only one involving deliberate deception."}],
 {"plain": "Factitious disorder is thought to be rare, around 1 in 100 hospital patients in some estimates, though it's largely unrecognized and the true rate is unknown.", "figure": "Estimated around 1% of hospital inpatients in some studies; true prevalence unknown because of deception", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "Treatment is challenging. The first step is a careful, non-punitive approach: a consistent clinician, limiting harmful tests and procedures, and offering psychological help without forcing a confession. Longer-term psychotherapy can address the underlying needs and trauma. Any co-occurring depression or personality difficulties are treated. When a child is involved, protecting the child comes first, through child protection services, with support for the whole family.",
  "evidence_based_options": ["A consistent, non-confrontational clinical relationship", "Limiting unnecessary and harmful investigations", "Psychotherapy for underlying trauma and needs", "Child protection procedures and family support when imposed on another"],
  "self_help_that_supports_care": ["If you recognize yourself: telling one clinician the truth is the bravest and most effective step", "Asking for therapy rather than another admission", "For families and clinicians: concern for the child's safety overrides everything", "Support for adults who were harmed as children by a caregiver's factitious behaviour"],
  "guideline_refs": ["src-dsm"]},
 "If you've been faking or causing illness and want to stop, a GP or mental health professional can help you without judgement. If you're worried a child is being made ill by a caregiver, contact child protection services or a child abuse helpline now.",
 "Genuinely experienced symptoms (somatic symptom disorder, FND) are not factitious. Faking for money, drugs, or to avoid duties is malingering, not a disorder. Illness anxiety involves real fear, not deception.",
 "People with factitious disorder can recover when they find a relationship safe enough to be honest in. Children affected by it can heal with the truth and support.",
 ["somatic-symptom-disorder", "functional-neurological-symptom-disorder", "child-abuse-and-neglect", "borderline-personality-disorder", "other-circumstances-a-clinician-may-note"],
 ["differential-diagnosis", "trauma", "attachment"],
 ["mind-side-by-side"], ("Soft line illustration of a doctor and a person talking quietly in a consulting room, a closed file on the desk, both calm, a window with soft light. Pastel terracotta and grey.", "A doctor and a person talk quietly in a consulting room with a closed file on the desk."),
 [DSM_M, src("src-nspcc-fii", "Fabricated or induced illness", "NSPCC (UK)", "https://www.nspcc.org.uk/what-is-child-abuse/types-of-abuse/fabricated-or-induced-illness/", note="Not opened.")],
 qs=["Find a primary prevalence source.", "Add child-protection helplines once crisis-lines.json exists."], sens="elevated", notes=["Imposed on another is child abuse; child-protection links required."], clin=True,
 subs=[{"title": "Imposed on self", "icd10cm_code": "F68.10", "text": "Faking or causing illness in oneself."}, {"title": "Imposed on another", "icd10cm_code": "F68.A", "text": "Faking or causing illness in a child or dependent. The diagnosis belongs to the perpetrator; the victim is treated as a victim of abuse."}]))
